{% set all_rows = doc.candidatos_sacramento_table | sort(attribute='catecumeno') %}
{% set dias = all_rows | map(attribute='dia') | unique | list %}
{% for dia in dias %}
{% if not loop.first %}
<div style="page-break-before: always;"></div>
{% endif %}
<h3>Candidatos ao sacramento de <strong> {{doc.sacramento}} para o {{ dia or 'Sem Dia Definido' }}</strong> - {{ doc.ano_lectivo }}</h3>
<h5>Com a permissão do reverendo padre passo a chamar os candidatos ao sacramento de {{doc.sacramento}}, os mesmos devem responder com voz audível Eis-me aqui Senhor, colocando-se em pé com as mãos postas</h6>

<table class="table table-bordered" style="font-size: 12px;">
    <thead>
        <tr>
            <th style="width:30px;">#</th>
            <th>Catecúmeno</th>
            <th>Padrinhos</th>
            <th style="width:60px;">Presença</th>
        </tr>
    </thead>
    <tbody>
    {% set counter = namespace(value=0) %}
    {% set dia_rows = all_rows | selectattr('dia', 'equalto', dia) | list %}

    {# Build a list of blocks:
       - each padrinho group = one block (sorted A->Z internally, anchored by first name)
       - each solo (no padrinho) = one block of 1
       Each block has: anchor_name (for sorting), rows (list) #}

    {% set ns = namespace(blocks=[], seen_padrinhos=[]) %}

    {# First pass: build padrinho group blocks #}
    {% for row in dia_rows %}
        {% if row.padrinhos %}
            {% if row.padrinhos not in ns.seen_padrinhos %}
                {% set ns.seen_padrinhos = ns.seen_padrinhos + [row.padrinhos] %}
                {# Collect all members of this group, sorted A->Z #}
                {% set group = dia_rows | selectattr('padrinhos', 'equalto', row.padrinhos) | sort(attribute='catecumeno') | list %}
                {# Anchor = first name in group alphabetically #}
                {% set ns.blocks = ns.blocks + [{'anchor': group[0].catecumeno, 'rows': group}] %}
            {% endif %}
        {% else %}
            {# Solo row: its own block, anchored by its own name #}
            {% set ns.blocks = ns.blocks + [{'anchor': row.catecumeno, 'rows': [row]}] %}
        {% endif %}
    {% endfor %}

    {# Sort all blocks by their anchor name A->Z #}
    {% set sorted_blocks = ns.blocks | sort(attribute='anchor') %}

    {% for block in sorted_blocks %}
        {% for row in block.rows %}
            {% set counter.value = counter.value + 1 %}
            <tr>
                <td>{{ counter.value }}</td>
                <td>{{ row.catecumeno }}</td>
                <td>{{ row.padrinhos or '' }}</td>
                <td>{{ '' }}</td>
            </tr>
        {% endfor %}
    {% endfor %}

    </tbody>
    </tbody>
    <tfoot>
        <tr>
            <td colspan="4" style="text-align:right; font-weight:bold;">
                Total: {{ dia_rows | length }}
            </td>
        </tr>
    </tfoot>
</table>
{% endfor %}

